window.ITEMS = {"instrument": "Digitale Kompetenzen Lehrpersonen Kanton Schwyz", "version": "SZ-2026.1-entwurf", "source": "DigCompEdu Bavaria, ALP Dillingen (Itemtexte ausgelesen am 28.09.2026); Kurzfassung Kanton Schwyz (Entwurf 30.09.2026)", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen"}, {"level": 2, "roman": "II", "label": "Entdecken"}, {"level": 3, "roman": "III", "label": "Anwenden"}, {"level": 4, "roman": "IV", "label": "Integrieren"}, {"level": 5, "roman": "V", "label": "Entwickeln"}, {"level": 6, "roman": "VI", "label": "Weitergeben"}], "areas": [{"id": "1", "title": "Berufsbezogenes Handeln", "short": "Berufsbezogenes Handeln", "description": "Digitale Medien für Kommunikation, Zusammenarbeit, Reflexion und die eigene Weiterbildung nutzen.", "subareas": [{"id": "1.1", "title": "Berufliche Kommunikation", "ki": false, "intro": "Beispiele: E-Mail, Schulportal, Messenger der Schule, Elternkommunikation, Videokonferenz", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "1.1-I", "text": "Ich kenne digitale Kanäle wie E-Mail oder Schulportal, nutze sie beruflich aber selten.", "rich": "Ich kenne digitale Kanäle wie E-Mail oder Schulportal, **nutze sie beruflich aber selten**.", "original": "Ich kenne digitale Medien wie E-Mail oder schulische Kommunikationsportale, nutze diese jedoch selten in beruflichen Kontexten."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "1.1-II", "text": "Ich probiere digitale Kanäle für den Austausch mit Lernenden, Eltern und Kollegium aus.", "rich": "Ich **probiere** digitale Kanäle für den Austausch mit **Lernenden, Eltern und Kollegium** aus.", "original": "Ich versuche digitale Medien adressatengerecht für die Kommunikation zu nutzen (z. B. mit Lernenden und Erziehungsberechtigten, im Kollegenkreis oder mit weiterem pädagogischem Personal)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "1.1-III", "text": "Ich kommuniziere regelmässig digital und halte mich an vereinbarte Abläufe und Regeln.", "rich": "Ich kommuniziere regelmässig digital und halte mich an **vereinbarte Abläufe und Regeln**.", "original": "Ich nutze geeignete digitale Kommunikationskanäle und kommuniziere sprachsensibel. Dabei berücksichtige ich Nutzungsbedingungen und vereinbarte Kommunikationsabläufe."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "1.1-IV", "text": "Ich wähle je nach Anliegen und Empfänger bewusst Kanal, Stil und Format.", "rich": "Ich wähle **je nach Anliegen und Empfänger** bewusst Kanal, Stil und Format.", "original": "Ich wähle aus einem breiten Repertoire an Kommunikationskanälen einen angemessenen Kanal, Stil und das Format für einen bestimmten Kommunikationszweck und -kontext aus."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "1.1-V", "text": "Ich überprüfe mit dem Kollegium, wie wir mit Eltern und Lernenden digital kommunizieren.", "rich": "Ich überprüfe mit dem Kollegium, wie wir **mit Eltern und Lernenden** digital kommunizieren.", "original": "Ich reflektiere, bewerte und diskutiere im Kollegenkreis die Art und Weise, wie digitale Medien effektiv für die schulische Kommunikation genutzt werden. Ich nutze digitale Medien, um schulorganisatorische Verfahren für Lernende und/oder Erziehungsberechtigte transparent zu machen und ihnen zu ermöglichen, informierte Entscheidungen zu treffen."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "1.1-VI", "text": "Ich entwickle Kommunikationskonzepte mit und gebe sie über die Schule hinaus weiter.", "rich": "Ich **entwickle Kommunikationskonzepte** mit und gebe sie über die Schule hinaus weiter.", "original": "Ich trage zur Entwicklung innovativer Konzepte und Strategien für den verantwortungsvollen Einsatz digitaler Technologien für die Kommunikation bei und multipliziere diese auch über die eigene Schule hinaus."}], "pd": {"primary": "Digitale Tools & Anwendungen", "secondary": "Team- und Beziehungsarbeit"}}, {"id": "1.2", "title": "Kollegiale Zusammenarbeit", "ki": false, "intro": "Beispiele: gemeinsame Ablage, Online-Plattform, Videokonferenz, Online-Communities für Lehrpersonen", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "1.2-I", "text": "Ich weiss, dass digitale Medien die Zusammenarbeit erleichtern, nutze sie aber selten.", "rich": "Ich weiss, dass digitale Medien die Zusammenarbeit erleichtern, **nutze sie aber selten**.", "original": "Ich bin mir bewusst, dass digitale Medien die Zusammenarbeit mit Kolleginnen und Kollegen - auch ausserhalb meiner Schule - unterstützen, nutze diese jedoch selten (z. B. kollaborative Online-Plattformen oder Videokonferenzwerkzeuge)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "1.2-II", "text": "Ich tausche mich mit Kolleginnen und Kollegen meiner Schule gelegentlich digital aus.", "rich": "Ich tausche mich **mit Kolleginnen und Kollegen meiner Schule** gelegentlich digital aus.", "original": "Ich versuche mit digitalen Medien mit Kolleginnen und Kollegen an meiner Schule zusammenzuarbeiten (z. B. um Inhalte, Wissen oder Meinungen auszutauschen)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "1.2-III", "text": "Ich teile regelmässig Material digital und hole mir Ideen aus Online-Communities.", "rich": "Ich teile regelmässig Material digital und hole mir Ideen aus **Online-Communities**.", "original": "Ich nutze Online-Communities (z. B. Twitter oder Internetforen für Lehrkräfte), um neue pädagogische Ressourcen oder Methoden zu entdecken. Auch nutze ich digitale Medien zum Teilen von Materialien und zum Austausch von Wissen und Meinungen in und ausserhalb meiner Schule."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "1.2-IV", "text": "Ich wähle passende Netzwerke bewusst aus, um Material gemeinsam zu erarbeiten.", "rich": "Ich wähle **passende Netzwerke** bewusst aus, um Material gemeinsam zu erarbeiten.", "original": "Ich wähle aktiv Online-Communities aus, um Ideen und digitale Ressourcen auszutauschen und zu erarbeiten (z. B. mebis-TeachSHARE )."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "1.2-V", "text": "Ich hole mir über berufliche Netzwerke Feedback zu meiner Praxis und entwickle mich weiter.", "rich": "Ich hole mir über berufliche Netzwerke **Feedback zu meiner Praxis** und entwickle mich weiter.", "original": "Durch die Nutzung beruflicher Kooperationsnetzwerke entwickle ich meine berufliche Praxis und meine Kompetenzen weiter. Dadurch erhalte ich Feedback zu pädagogischen Konzepten und Unterrichtsideen."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "1.2-VI", "text": "Ich unterstütze Lehrpersonen anderer Schulen über Online-Communities bei ihrer Weiterentwicklung.", "rich": "Ich **unterstütze Lehrpersonen anderer Schulen** über Online-Communities bei ihrer Weiterentwicklung.", "original": "Mit Hilfe von Online-Communities trage ich zur innovativen Weiterentwicklung pädagogischer Praktiken bei. Dabei fördere und unterstütze ich Lehrkräfte auch ausserhalb des eigenen Kollegiums bei der Weiterentwicklung ihrer digitalen und pädagogischen Kompetenzen."}], "pd": {"primary": "Team- und Beziehungsarbeit", "secondary": "Digitale Tools & Anwendungen"}}, {"id": "1.3", "title": "Reflektiertes Handeln", "ki": false, "intro": "Worum es geht: die eigene digitale Praxis reflektieren und gezielt weiterentwickeln.", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "1.3-I", "text": "Ich habe wenig Erfahrung und weiss noch nicht, wie ich mich weiterentwickeln kann.", "rich": "Ich habe wenig Erfahrung und **weiss noch nicht, wie ich mich weiterentwickeln** kann.", "original": "Ich bin mir bewusst, dass digitale Medien im schulischen Kontext eingesetzt werden können. Jedoch habe ich hierin kaum Erfahrung und bin mir über die Möglichkeiten noch im Unklaren, wie ich mich hier weiterentwickeln kann."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "1.3-II", "text": "Ich kenne meine Grenzen und suche nach Wegen, meine digitalen Kompetenzen zu erweitern.", "rich": "Ich **kenne meine Grenzen** und suche nach Wegen, meine digitalen Kompetenzen zu erweitern.", "original": "Ich suche nach Wegen, meine medienbezogenen Lehrkompetenzen weiterzuentwickeln. Dabei bin ich mir der Grenzen meiner eigenen digitalen Kompetenz wie auch notwendiger individueller Entwicklungsbereiche bewusst."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "1.3-III", "text": "Ich experimentiere regelmässig mit digitalen Ansätzen und lerne dabei von Kolleginnen und Kollegen.", "rich": "Ich **experimentiere regelmässig** mit digitalen Ansätzen und lerne dabei von Kolleginnen und Kollegen.", "original": "Ich nutze digitale Medien bewusst in verschiedenen schulischen Kontexten und zu unterschiedlichen Zwecken, um mit zeitgemässen pädagogischen Ansätzen zu experimentieren. Dabei möchte ich meine medienbezogenen Lehrkompetenzen durch Erproben und Peer-Learning weiterentwickeln und verbessern."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "1.3-IV", "text": "Ich suche gezielt nach bewährten Praktiken und Kursen, um meinen Unterricht zu verbessern.", "rich": "Ich suche gezielt nach **bewährten Praktiken und Kursen**, um meinen Unterricht zu verbessern.", "original": "Ich analysiere und diskutiere mit Kolleginnen und Kollegen, wie die Nutzung von digitalen Medien zur Erneuerung und Verbesserung der Unterrichtspraxis realisiert werden kann. Ich suche aktiv nach bewährten Praktiken, Kursen oder anderen Ratschlägen, um meine eigenen digitalen pädagogischen Konzepte zu verbessern und digitale Kompetenzen auszuweiten."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "1.3-V", "text": "Ich verfolge neue Erkenntnisse und diskutiere die digitale Praxis unserer Schule im Kollegium.", "rich": "Ich verfolge **neue Erkenntnisse** und diskutiere die digitale Praxis unserer Schule im Kollegium.", "original": "Ich unterstütze Kolleginnen und Kollegen dabei, ihre digitalen Kompetenzen weiterzuentwickeln. Ich informiere mich regelmässig, z. B. in Fachzeitschriften oder im Internet über aktuelle wissenschaftliche Erkenntnisse und übertrage diese in meine Praxis. Zudem bewerte, reflektiere und diskutiere ich über Konzepte und Praxis der Schule hinsichtlich der Nutzung digitaler Medien (z.B. Teilnahme an Kongressen und Organisation von SchiLFS)"}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "1.3-VI", "text": "Ich entwickle mit anderen, auch mit der Forschung, Strategien für eine bessere Bildungspraxis.", "rich": "Ich **entwickle mit anderen**, auch mit der Forschung, Strategien für eine bessere Bildungspraxis.", "original": "Mit Hilfe digitaler Medien trage ich dazu bei, individuell oder gemeinsam mit Kolleginnen und Kollegen eine Strategie zur Verbesserung der Bildungspraxis zu entwickeln. Ich reflektiere und evaluiere mit Kolleginnen und Kollegen und/oder Wissenschaftlerinnen und Wissenschaftlern verschiedene digitale Praktiken, Methoden und Strategien mit dem Ziel, innovative Konzepte zu entwickeln. (z.B. Mitwirkung an Kongressen oder Barcamps)"}], "pd": {"primary": "Gesundheit & Professionalisierung", "secondary": "Didaktik & Unterrichtsdesign"}}, {"id": "1.4", "title": "Kontinuierliche Weiterentwicklung", "ki": false, "intro": "Beispiele: Online-Kurse, Webinare, Erklärvideos, Fachblogs, Bildungsportale", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "1.4-I", "text": "Ich weiss, dass ich mich online weiterbilden könnte, nutze dies aber kaum.", "rich": "Ich weiss, dass ich mich **online weiterbilden** könnte, nutze dies aber kaum.", "original": "Ich bin mir bewusst, dass ich mit Hilfe des Internets mein fachspezifisches oder pädagogisches Wissen aktualisieren oder meine Fähigkeiten erweitern kann."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "1.4-II", "text": "Ich suche gelegentlich online nach Informationen für mein Fach oder meinen Unterricht.", "rich": "Ich suche gelegentlich online nach **Informationen für mein Fach** oder meinen Unterricht.", "original": "Ich suche nach Wegen, mit Hilfe des Internets mein fachspezifisches oder pädagogisches Wissen zu aktualisieren. (z.B. Onlineportale, Edu-Blogs, Themenseiten des ISB)"}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "1.4-III", "text": "Ich finde regelmässig passende Weiterbildungsangebote über das Internet.", "rich": "Ich finde regelmässig **passende Weiterbildungsangebote** über das Internet.", "original": "Ich nutze das Internet, um gezielt passende Fort- und Weiterbildungsangebote und andere Chancen für die berufliche Weiterentwicklung zu identifizieren. (z. B. Identifizierung geeigneter Fortbildungsveranstaltungen)"}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "1.4-IV", "text": "Ich wähle Online-Kurse und Materialien nach meinem Entwicklungsbedarf aus.", "rich": "Ich wähle Online-Kurse und Materialien **nach meinem Entwicklungsbedarf** aus.", "original": "Ich wähle zielgerichtet Online-Fortbildungen (z. B. eSessions) oder digitales Weiterbildungsmaterial und Video-Tutorials als Quelle für meine berufliche Weiterentwicklung aus."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "1.4-V", "text": "Ich berate Kolleginnen und Kollegen bei der Wahl von Online-Weiterbildungen.", "rich": "Ich **berate Kolleginnen und Kollegen** bei der Wahl von Online-Weiterbildungen.", "original": "Ich berate meine Kolleginnen und Kollegen bei der Wahl von Online-Fortbildungsmöglichkeiten. Dazu sichte ich eine Vielzahl von Angeboten und wähle diejenigen aus, die meinen Weiterentwicklungsbedürfnissen und ggf. denen meiner Kolleginnen und Kollegen am besten entsprechen. Ich nehme aktiv an Online-Fortbildungen teil und trage durch gezieltes Feedback zu deren Verbesserung bei."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "1.4-VI", "text": "Ich gestalte selbst Weiterbildungsangebote oder Materialien für andere Lehrpersonen.", "rich": "Ich **gestalte selbst Weiterbildungsangebote** oder Materialien für andere Lehrpersonen.", "original": "Ich fördere Kolleginnen und Kollegen mit Hilfe digitaler Technologien (z. B. im Rahmen von Fortbildungen, durch persönliche Blogs oder indem ich für sie neues digitales Fortbildungsmaterial entwickle)."}], "pd": {"primary": "Gesundheit & Professionalisierung", "secondary": "Digitale Tools & Anwendungen"}}]}, {"id": "2", "title": "Digitale Ressourcen", "short": "Digitale Ressourcen", "description": "Digitale Materialien finden, erstellen, anpassen, ordnen und rechtlich korrekt teilen.", "subareas": [{"id": "2.1", "title": "Auswählen digitaler Ressourcen", "ki": false, "intro": "Beispiele: Arbeitsblätter, Lernvideos, Online-Quiz, Bildungsplattformen, offene Lernmaterialien (OER)", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "2.1-I", "text": "Ich weiss, dass ich online nach Unterrichtsmaterial suchen kann, tue es aber selten.", "rich": "Ich weiss, dass ich online nach Unterrichtsmaterial suchen kann, **tue es aber selten**.", "original": "Ich bin mir bewusst, dass ich online nach Lehr- und Lernressourcen suchen kann, nutze die Möglichkeit jedoch nicht oder nur selten (z.B. Arbeitsmaterial, Onlinequizze oder Videos)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "2.1-II", "text": "Ich finde digitales Material mit einfachen Suchstrategien, etwa über eine Bildungsplattform.", "rich": "Ich finde digitales Material mit **einfachen Suchstrategien**, etwa über eine Bildungsplattform.", "original": "Ich nutze einfache Internet-Suchstrategien, um digitale Lehr- und Lernressourcen zum Beispiel auf Bildungsplattformen wie mebis zu finden."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "2.1-III", "text": "Ich suche regelmässig auf verschiedenen Plattformen nach Material, das zu meiner Klasse passt.", "rich": "Ich suche regelmässig auf **verschiedenen Plattformen** nach Material, das zu meiner Klasse passt.", "original": "Ich identifiziere und verwende geeignete Online-Werkzeuge und Bildungsplattformen, um nach vielfältigen digitalen Ressourcen zu suchen, die dem Bildungsbedarf meiner Lernenden entsprechen (z. B. mebis)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "2.1-IV", "text": "Ich wähle Material nach klaren Kriterien wie Qualität, Zuverlässigkeit und Lizenz aus.", "rich": "Ich wähle Material **nach klaren Kriterien** wie Qualität, Zuverlässigkeit und Lizenz aus.", "original": "Ich wähle digitale Ressourcen auf der Grundlage komplexer Kriterien aus und entwickle meine Suchkriterien mit Blick auf den intendierten Kompetenzerwerb weiter, um meine spezifischen Lehr- und Lernziele zu erfüllen (z. B. Bildungswert, Relevanz, Zuverlässigkeit, Gültigkeit, Qualität, Lizenzierung)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "2.1-V", "text": "Ich überprüfe meine Auswahlkriterien laufend und berate Kolleginnen und Kollegen.", "rich": "Ich **überprüfe meine Auswahlkriterien** laufend und berate Kolleginnen und Kollegen.", "original": "Ich reflektiere und bewerte meine Suchergebnisse umfassend und passe meine Auswahlkriterien ggf. neu und flexibel an (z. B. Prüfung von Genauigkeit und Neutralität). Ausserdem berate ich meine Kolleginnen und Kollegen."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "2.1-VI", "text": "Ich entwickle neue Strategien zur Auswahl digitaler Ressourcen und gebe sie weiter.", "rich": "Ich **entwickle neue Strategien** zur Auswahl digitaler Ressourcen und gebe sie weiter.", "original": "Ich entwickle und multipliziere innovative Strategien zur Auswahl, Identifizierung und Auswertung digitaler Ressourcen."}], "pd": {"primary": "Digitale Tools & Anwendungen", "secondary": "Medienkompetenz & Medienkritik"}}, {"id": "2.2", "title": "Erstellen und Anpassen digitaler Ressourcen", "ki": false, "intro": "Beispiele: Präsentationen, interaktive Übungen, Erklärvideos, Lernpfade, digitale Lernumgebungen", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "2.2-I", "text": "Ich weiss, dass ich Material digital erstellen kann, verzichte aber meist darauf.", "rich": "Ich weiss, dass ich Material digital erstellen kann, **verzichte aber meist darauf**.", "original": "Ich bin mir der Tatsache bewusst, dass ich bestehende Ressourcen in digitaler Form erstellen oder anpassen kann, verzichte aber meist darauf (z. B. Textverarbeitung, Bilder, Fotos, Audio, Video)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "2.2-II", "text": "Ich erstelle erste einfache Materialien, etwa Texte, Präsentationen oder Bilder.", "rich": "Ich erstelle **erste einfache Materialien**, etwa Texte, Präsentationen oder Bilder.", "original": "Ich entdecke für mich neue digitale Ressourcen und habe bereits versucht, eigene Ressourcen mit Hilfe von einfachen Tools zu erstellen oder anzupassen (z. B. Textverarbeitung, Bilder, Tabellen, Präsentationen, Audio- oder Videodateien)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "2.2-III", "text": "Ich erstelle regelmässig digitale Materialien und passe sie an meine Lernenden an.", "rich": "Ich erstelle regelmässig digitale Materialien und **passe sie an meine Lernenden an**.", "original": "Ich identifiziere und verwende geeignete digitale Tools, um Ressourcen zu erstellen und passe sie ggf. sach-und situationsgerecht an, um den Bedürfnissen der Lernenden zu entsprechen (z. B. interaktive Texte, Multimedia-Präsentationen, Quizze, Spiele, Online-Aktivitäten und Unterricht)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "2.2-IV", "text": "Ich gestalte digitale Materialien bewusst nach Lernzielen und Gestaltungsprinzipien.", "rich": "Ich gestalte digitale Materialien bewusst **nach Lernzielen und Gestaltungsprinzipien**.", "original": "Ich wende Gestaltungsprinzipien und -prozesse an, um digitale Ressourcen zu schaffen oder systematisch anzupassen, damit sie den Lehr- und Lernzielen entsprechen (z.B. Entwerfen eines Onlinelernspiels, digitale Lernumgebungen, Erklärvideos)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "2.2-V", "text": "Ich entwickle komplexe interaktive Lernaktivitäten und teile mein Wissen im Kollegium.", "rich": "Ich entwickle **komplexe interaktive Lernaktivitäten** und teile mein Wissen im Kollegium.", "original": "Ich erstelle Konzepte für komplexe und interaktive digitale Lernaktivitäten und/oder passe diese an (z. B. interaktive Arbeitsbögen, Lernaktivitäten wie Wikis, Blogs, Lernpfade). Ich reflektiere kritisch, inwiefern sich verschiedene Methoden für die Erstellung digitaler Ressourcen eignen und gebe mein Wissen im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "2.2-VI", "text": "Ich entwickle innovative Lernumgebungen mit neuen Technologien und gebe sie weiter.", "rich": "Ich **entwickle innovative Lernumgebungen** mit neuen Technologien und gebe sie weiter.", "original": "Ich entwickle und multipliziere komplexe und innovative digitale Ressourcen für Lehr-/Lernkontexte (z. B.digitale Lernumgebungen mit 3D-Animationen) unter Berücksichtigung neuester technischer Entwicklungen."}], "pd": {"primary": "Digitale Tools & Anwendungen", "secondary": "Künstliche Intelligenz"}}, {"id": "2.3", "title": "Organisieren, Schützen und Teilen digitaler Ressourcen", "ki": false, "intro": "Beispiele: Ablage in der Cloud, Links teilen, Lernplattform, Urheberrecht, Schutz von Personendaten", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "2.3-I", "text": "Ich speichere digitale Materialien für mich und weiss, dass Urheberrechte gelten.", "rich": "Ich speichere digitale Materialien für mich und weiss, dass **Urheberrechte** gelten.", "original": "Ich speichere und verwalte digitale Ressourcen, wie z. B. Arbeitsmaterial, Fotos oder Videos zur eigenen Verwendung. Ich bin mir der Tatsache bewusst, dass einige der im Internet verbreiteten Ressourcen dem Urheberrecht unterliegen."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "2.3-II", "text": "Ich teile Material per Link oder Anhang und beachte dabei das Urheberrecht.", "rich": "Ich teile Material **per Link oder Anhang** und beachte dabei das Urheberrecht.", "original": "Ich teile Unterrichtsmaterialien (z. B. Texte und interaktive Aufgaben) unter Beachtung des Urheberrechts als Anhang einer Nachricht oder durch die Weitergabe von Links."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "2.3-III", "text": "Ich teile Material regelmässig und schütze sensible Daten wie Beurteilungen.", "rich": "Ich teile Material regelmässig und **schütze sensible Daten** wie Beurteilungen.", "original": "Ich teile verantwortungsvoll Unterrichtsmaterialien (z. B. Verschlüsselung von Texten, Videos, Lernspiele und Aufgaben) im Rahmen des digital gestützten Lernens und schütze sensible Inhalte wie Leistungserhebungen oder Berichte der Lehrkräfte effektiv."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "2.3-IV", "text": "Ich stelle Material geordnet auf einer Lernplattform bereit und kennzeichne Quellen korrekt.", "rich": "Ich stelle Material **geordnet auf einer Lernplattform** bereit und kennzeichne Quellen korrekt.", "original": "Ich teile Ressourcen (z. B. Texte, Videos, Lernspiele und interaktive Aufgaben) professionell, indem ich sie in digitale Lernumgebungen einbette. Ich schütze persönliche und sensible Daten effektiv. Ich kennzeichne Ressourcen, die dem Urheberrecht unterliegen, richtig."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "2.3-V", "text": "Ich überarbeite Materialien für Lernende und stelle sie auch dem Kollegium zur Verfügung.", "rich": "Ich **überarbeite Materialien** für Lernende und stelle sie auch dem Kollegium zur Verfügung.", "original": "Ich durchdenke den Sinn bestehender digitaler Ressourcen und gestalte sie ggf. neu, um sie in interaktive, auf den Lernenden ausgerichtete Aktivitäten zu integrieren. Ich veröffentliche die Ressourcen (online) und mache sie so für die Lernenden und andere Lehrkräfte zugänglich (z. B. Anpassung digitaler Ressourcen und digital erweiterter Aufgaben in einem Online-Kurs, einer Online-Beurteilung, einem kollaborativen Online-Projekt, einem Wiki, einem Blog oder einem virtuellen Lernraum)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "2.3-VI", "text": "Ich veröffentliche eigene Materialien mit Lizenz, auch für Lehrpersonen anderer Schulen.", "rich": "Ich **veröffentliche eigene Materialien mit Lizenz**, auch für Lehrpersonen anderer Schulen.", "original": "Ich erstelle innovative digitale Ressourcen selbst, lizenziere sie und veröffentliche sie für die Lernenden und andere Lehrkräfte (z. B. digital erweiterte Aufgaben in einem Online-Kurs, einer Online-Beurteilung, einem kollaborativen Online-Projekt oder einem virtuellen Lernraum)."}], "pd": {"primary": "Medienkompetenz & Medienkritik", "secondary": "Digitale Tools & Anwendungen"}}]}, {"id": "3", "title": "Lehren und Lernen", "short": "Lehren und Lernen", "description": "Digitale Medien im Unterricht einsetzen, Lernprozesse begleiten, kooperatives und selbstgesteuertes Lernen fördern.", "subareas": [{"id": "3.1", "title": "Lehren", "ki": false, "intro": "Beispiele: Apps, Lernplattform, interaktive Wandtafel, Simulationen, Tools für die Zusammenarbeit", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "3.1-I", "text": "Ich weiss, dass digitale Technologien den Unterricht unterstützen können, setze sie aber kaum ein.", "rich": "Ich weiss, dass digitale Technologien den Unterricht unterstützen können, **setze sie aber kaum ein**.", "original": "Ich bin mir bewusst, dass digitale Technologien wie beispielsweise Programme, Apps und cloudbasierte Ressourcen das Lehren und Lernen unterstützen und verbessern können, nutze diese Möglichkeit jedoch selten."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "3.1-II", "text": "Ich probiere einzelne digitale Werkzeuge im Unterricht aus.", "rich": "Ich **probiere einzelne** digitale Werkzeuge im Unterricht **aus**.", "original": "Ich versuche digitale Technologien wie beispielsweise Programme, mobile Apps und Tools, onlinebasierte Ressourcen oder interaktive Whiteboards zur Unterstützung oder Verbesserung meiner Unterrichtspraxis zu nutzen und die Lernenden zur Nutzung zu motivieren."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "3.1-III", "text": "Digitale Technologien sind ein fester Bestandteil meines Unterrichts und aktivieren die Lernenden.", "rich": "Digitale Technologien sind ein **fester Bestandteil** meines Unterrichts und aktivieren die Lernenden.", "original": "Ich verwende sach- und situationsgerecht verschiedene digitale Technologien, die innovative pädagogische Ansätze unterstützen können und die aktive Beteiligung der Lernenden an ihren Lernprozessen fördern. Diese umfassen z.B. problembasiertes Lernen, Selbstbewertung und Coaching durch andere Lernende."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "3.1-IV", "text": "Ich plane den Einsatz digitaler Technologien von den Lernzielen her.", "rich": "Ich **plane** den Einsatz digitaler Technologien **von den Lernzielen her**.", "original": "Ich wähle digitale Technologien (z.B. Simulationen, interaktive Online-Tools und kollaborative Umgebungen) systematisch aus, um die Lernziele in meinen Lernkonzepten zu erreichen."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "3.1-V", "text": "Ich überprüfe, was wirkt, und teile meine Erfahrungen im Kollegium.", "rich": "Ich **überprüfe, was wirkt**, und teile meine Erfahrungen im Kollegium.", "original": "Ich bewerte und gestalte den Einsatz digitaler Technologien zur flexiblen Anpassung von Lehrmethoden und innovativen Lernansätzen wie z.B. Coaching durch andere Lernende, Modellierung und Beratung. Ich berate mit Kolleginnen und Kollegen meine Strategien und gebe dieses Wissen im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "3.1-VI", "text": "Ich gestalte neue Lernformen mit und gebe sie in Weiterbildungen weiter.", "rich": "Ich **gestalte neue Lernformen** mit und gebe sie in Weiterbildungen weiter.", "original": "Ich trage zur Entwicklung innovativer Lernpraktiken mit digitalen Technologien bei wie z.B. Online-Workshops, Co-Teaching und Reflexionsgespräche über die Wirksamkeit des Einsatzes digitaler Technologien. Diese gebe ich in regionalen und überregionalen Fortbildungen weiter."}], "pd": {"primary": "Didaktik & Unterrichtsdesign", "secondary": "Digitale Tools & Anwendungen"}}, {"id": "3.2", "title": "Lernbegleitung", "ki": false, "intro": "Beispiele: automatisches Feedback, Chat, Umfrage, gemeinsames Online-Dokument, Lernverlauf auf der Plattform", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "3.2-I", "text": "Ich weiss, dass digitale Mittel beim Begleiten des Lernens helfen, nutze sie aber kaum.", "rich": "Ich weiss, dass digitale Mittel beim Begleiten des Lernens helfen, **nutze sie aber kaum**.", "original": "Ich bin mir bewusst, dass digitale Technologien dazu dienen können, Feedback zu geben und über Lehr- und Lernmethoden zu reflektieren, nutze diese Möglichkeit jedoch kaum oder gar nicht."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "3.2-II", "text": "Ich probiere digitale Wege aus, um Lernenden Feedback und Unterstützung zu geben.", "rich": "Ich probiere digitale Wege aus, um Lernenden **Feedback und Unterstützung** zu geben.", "original": "Ich versuche digitale Technologien zu nutzen, um den Lernenden Feedback und Unterstützung zu geben (z.B. automatisiertes Feedback, Links zu Online-Tutorials, Chat)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "3.2-III", "text": "Ich gebe regelmässig digital Rückmeldung und lasse Lernende über ihr Lernen nachdenken.", "rich": "Ich gebe regelmässig digital Rückmeldung und lasse Lernende **über ihr Lernen nachdenken**.", "original": "Ich verwende, je nach Anforderung, verschiedene digitale Technologien (z.B.Chats, Diskussionsforen und Umfragen im Unterricht) um den Lernenden ein Feedback zu geben und ihnen die Möglichkeit einzuräumen, über ihr Lernen nachzudenken."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "3.2-IV", "text": "Ich setze digitale Mittel bewusst für die Selbsteinschätzung der Lernenden ein.", "rich": "Ich setze digitale Mittel bewusst für die **Selbsteinschätzung der Lernenden** ein.", "original": "Ich setze digitale Technologien (z.B. gemeinsame Online-Dokumente, Aufzeichnungen von Lernaktivitäten und begleitete Reflexion) systematisch ein, um den Lernenden die Möglichkeit zu geben, eine Selbstbewertung durchzuführen und dadurch an der Gestaltung des Lernprozesses teilzuhaben."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "3.2-V", "text": "Ich werte digitale Lernspuren aus, passe meine Begleitung an und teile Erfahrungen im Kollegium.", "rich": "Ich **werte digitale Lernspuren aus**, passe meine Begleitung an und teile Erfahrungen im Kollegium.", "original": "Ich analysiere und bewerte Lernen neu unter Berücksichtigung von Erkenntnissen, die durch digitale Technologien (z.B. Aufzeichnungen von Lernaktivitäten und Learning Analytics) gewonnen wurden. Ich berate mit Kolleginnen und Kollegen meine Strategien und gebe dieses Wissen im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "3.2-VI", "text": "Ich entwickle neue Formen der Lernbegleitung und gebe sie in Weiterbildungen weiter.", "rich": "Ich **entwickle neue Formen der Lernbegleitung** und gebe sie in Weiterbildungen weiter.", "original": "Ich entwickle innovative Ansätze zur Unterstützung und Begleitung des Lernprozesses. Im Zuge dessen werden digitale Technologien (z.B. Diskussionsforen, gemeinsame Dokumente und FAQ-Sheets) eingesetzt. Diese gebe ich in regionalen und überregionalen Fortbildungen weiter."}], "pd": {"primary": "Didaktik & Unterrichtsdesign", "secondary": "Leistung, Feedback & Lernstand"}}, {"id": "3.3", "title": "Kollaboratives Lernen", "ki": false, "intro": "Beispiele: gemeinsame Online-Dokumente, Forum, Wiki, Projektplattform, virtueller Austausch", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "3.3-I", "text": "Ich weiss, dass digitale Mittel die Zusammenarbeit der Lernenden fördern, nutze sie aber selten.", "rich": "Ich weiss, dass digitale Mittel die Zusammenarbeit der Lernenden fördern, **nutze sie aber selten**.", "original": "Ich bin mir bewusst, dass digitale Technologien genutzt werden können, um die Zusammenarbeit der Lernenden beim Lernen (z.B. im Rahmen von Online-Zusammenarbeit und der gemeinsamen Nutzung von Lernressourcen) zu fördern und zu verbessern, nutze diese Möglichkeit jedoch selten oder nicht."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "3.3-II", "text": "Ich lasse Lernende ab und zu digital zusammenarbeiten, etwa in einem gemeinsamen Dokument.", "rich": "Ich lasse Lernende ab und zu digital zusammenarbeiten, etwa **in einem gemeinsamen Dokument**.", "original": "Ich versuche digitale Technologien (z.B. gemeinsame Dokumente und Beiträge in Foren) zur Unterstützung und Verbesserung kollaborativer Aktivitäten von Lernenden zu nutzen und die Lernenden dazu zu motivieren."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "3.3-III", "text": "Lernende arbeiten in meinem Unterricht regelmässig digital zusammen.", "rich": "Lernende arbeiten in meinem Unterricht **regelmässig digital zusammen**.", "original": "Ich verwende verschiedene digitale Technologien und Medien situationsgerecht (z.B. Foren, Wikis und kollaborative Lernprodukte), um das kollaborative Lernen zu unterstützen und zu verbessern."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "3.3-IV", "text": "Ich plane digitale Zusammenarbeit passend zu den Lernzielen meiner Einheiten.", "rich": "Ich plane digitale Zusammenarbeit **passend zu den Lernzielen** meiner Einheiten.", "original": "Ich wende digitale Technologien systematisch in meinen Lernkonzepten an, um das kollaborative Lernen zu verbessern und zu unterstützen (z.B. im Rahmen von Gruppenreflexion, Projektentwicklung und Austausch)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "3.3-V", "text": "Ich entwickle digitale Formen der Zusammenarbeit weiter und teile Erfahrungen im Kollegium.", "rich": "Ich **entwickle digitale Formen der Zusammenarbeit weiter** und teile Erfahrungen im Kollegium.", "original": "Ich entwickle die Nutzung digitaler Technologien zum Wissensaufbau weiter (z.B. die gemeinsame Teilnahme an Projekten, der virtuelle Austausch und die Nutzung digitaler Tools für Kommunikation). Ich berate mit Kolleginnen und Kollegen meine Strategien und gebe dieses Wissen im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "3.3-VI", "text": "Ich gestalte neue kollaborative Lernszenarien und gebe sie in Weiterbildungen weiter.", "rich": "Ich **gestalte neue kollaborative Lernszenarien** und gebe sie in Weiterbildungen weiter.", "original": "Ich entwickle innovative Lernszenarien, indem ich Möglichkeiten der Zusammenarbeit zur Unterstützung des Lernens (z.B. Nutzung synchroner und asynchroner Online-Umgebungen sowie Mitgestaltung und gemeinsame Erstellung von Lernmaterial) anbiete. Diese gebe ich in regionalen und überregionalen Fortbildungen weiter."}], "pd": {"primary": "Didaktik & Unterrichtsdesign", "secondary": "Team- und Beziehungsarbeit"}}, {"id": "3.4", "title": "Selbstgesteuertes Lernen", "ki": false, "intro": "Beispiele: digitaler Lernplan, Lernjournal, Fortschrittsanzeige, E-Portfolio, Lernplattform", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "3.4-I", "text": "Ich weiss, dass digitale Mittel selbstständiges Lernen fördern, nutze sie aber kaum.", "rich": "Ich weiss, dass digitale Mittel selbstständiges Lernen fördern, **nutze sie aber kaum**.", "original": "Ich bin mir bewusst, dass digitale Technologien genutzt werden können, um aktives und autonomes Lernen (z.B. Planung, Zielsetzung und Aufzeichnung von Fortschritten) zu fördern, nutze diese Möglichkeit jedoch kaum oder gar nicht."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "3.4-II", "text": "Ich probiere digitale Hilfen für die Lernplanung der Lernenden aus, etwa einen Lernplan.", "rich": "Ich probiere digitale Hilfen für die **Lernplanung der Lernenden** aus, etwa einen Lernplan.", "original": "Ich versuche digitale Technologien zur Unterstützung der Lernenden bei der Planung ihres eigenen Lernens (z.B. in der Verwendung von digitalen Kalendern und Aufzeichnung von Fortschritten) zu nutzen und sie dazu zu motivieren."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "3.4-III", "text": "Lernende planen und steuern ihr Lernen regelmässig mit digitalen Mitteln.", "rich": "Lernende **planen und steuern ihr Lernen** regelmässig mit digitalen Mitteln.", "original": "Ich verwende verschiedene digitale Technologien (z.B. Online-Lernumgebungen, Werkzeuge und Räume für die Zusammenarbeit) situationsgerecht, um die Lernenden bei der Planung und Steuerung ihres eigenen Lernens zu unterstützen."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "3.4-IV", "text": "Ich setze digitale Mittel bewusst ein, um Selbstständigkeit und Selbstreflexion zu fördern.", "rich": "Ich setze digitale Mittel bewusst ein, um **Selbstständigkeit und Selbstreflexion** zu fördern.", "original": "Ich wende digitale Technologien in meinen Lernkonzepten systematisch auf der Grundlage ihrer Eigenschaften an, um die selbstgesteuerten Lernfähigkeiten und die Autonomie der Lernenden zu steuern und zu fördern. Diese umfassen z.B. Eigeninitiative in Bezug auf das eigene Lernen, kreatives Eingehen auf neue Lernsituationen und Selbstreflexion, um den eigenen Fortschritt zu planen."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "3.4-V", "text": "Ich passe digitale Werkzeuge für selbstgesteuertes Lernen an und teile Erfahrungen im Kollegium.", "rich": "Ich **passe digitale Werkzeuge** für selbstgesteuertes Lernen an und teile Erfahrungen im Kollegium.", "original": "Ich gestalte digitale Technologien und passe diese an, damit sie von Lernenden zur Förderung ihres selbstgesteuerten Lernens eingesetzt werden, indem sie z.B. über ihre Lernstrategien reflektieren oder Lernergebnisse sammeln und teilen. Ich berate mit Kolleginnen und Kollegen meine Strategien und gebe dieses Wissen im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "3.4-VI", "text": "Ich entwickle neue Lernsettings für selbstgesteuertes Lernen und gebe sie weiter.", "rich": "Ich **entwickle neue Lernsettings** für selbstgesteuertes Lernen und gebe sie weiter.", "original": "Ich entwickle innovative pädagogischer Strategien und Praktiken für das selbstgesteuerte Lernen (z.B. Makerspaces und Lernräume mit digitalen Technologien). Diese gebe ich in regionalen und überregionalen Fortbildungen weiter."}], "pd": {"primary": "Didaktik & Unterrichtsdesign", "secondary": "Inklusion, Differenzierung & Sprachbildung"}}]}, {"id": "4", "title": "Lerndiagnose und Feedback", "short": "Lerndiagnose und Feedback", "description": "Mit digitalen Mitteln Lernstände erheben, auswerten und Rückmeldungen geben.", "subareas": [{"id": "4.1", "title": "Lernstandserhebung", "ki": false, "intro": "Beispiele: Quiz, Online-Umfrage, digitaler Test, Bewertungsraster, E-Portfolio, Peer-Feedback", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "4.1-I", "text": "Ich weiss, dass es digitale Werkzeuge für Lernkontrollen gibt, verwende sie aber kaum.", "rich": "Ich weiss, dass es digitale Werkzeuge für Lernkontrollen gibt, **verwende sie aber kaum**.", "original": "Ich bin mir bewusst, dass es digitale Medien und Werkzeuge für die Lernstandserhebung gibt, nutze sie jedoch selten oder nie (z.B. digitale Quizze, Online-Umfragen)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "4.1-II", "text": "Ich übertrage einzelne herkömmliche Lernkontrollen in digitale Form, etwa ein Quiz.", "rich": "Ich **übertrage** einzelne herkömmliche Lernkontrollen **in digitale Form**, etwa ein Quiz.", "original": "Ich setze digitale Medien für überwiegend traditionelle Formen der Lernstandserhebung ein (z.B. Textverarbeitungswerkzeuge, Tools zur Erzeugung von Online-Abfragen wie mobile Apps oder Spiele)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "4.1-III", "text": "Ich erfasse den Lernstand regelmässig mit verschiedenen digitalen Formen.", "rich": "Ich erfasse den Lernstand **regelmässig mit verschiedenen** digitalen Formen.", "original": "Ich verwende verschiedene digitale Technologien zur Bewertung und passe diese bei Bedarf an (z. B. Erstellen eines digitalen Tests, Nutzung von Bewertungsplattformen, die den Schülern zeitnahes Feedback geben)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "4.1-IV", "text": "Ich wähle die digitale Form danach aus, was genau ich erfassen will.", "rich": "Ich wähle die digitale Form danach aus, **was genau ich erfassen will**.", "original": "Ich wähle digitale Technologien aus, um bestimmte Aspekte der Bewertung systematisch zu unterstützen und die Art des zu evaluierenden Lernergebnisses bestmöglich zu erfassen (z. B. Rubriken zur Selbstreflexion, Aufgaben, die den Lernenden zeitnahes Feedback bieten, gemeinsam genutzte Dokumente, die Peer-Reviews/Feedback unterstützen)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "4.1-V", "text": "Ich verbessere meine digitalen Bewertungsformen laufend und teile sie im Kollegium.", "rich": "Ich **verbessere** meine digitalen Bewertungsformen laufend und teile sie im Kollegium.", "original": "Ich wähle aus einer Vielzahl digitaler Bewertungstools und -formaten zur Lernstandserhebung kritisch aus, passe diese an und multipliziere sie im Kreis der Kolleginnen und Kollegen (z.B. e-Portfolios, Formate der Selbst- und Peerbewertung)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "4.1-VI", "text": "Ich entwickle neue Bewertungsformen, auch für überfachliche Kompetenzen, und gebe sie weiter.", "rich": "Ich **entwickle neue** Bewertungsformen, auch für überfachliche Kompetenzen, und gebe sie weiter.", "original": "Ich entwickle neue digitale Bewertungsformate, die es auch ermöglichen, innovative pädagogische Ansätze und überfachliche Fertigkeiten bewerten zu können (z. B. Selbst- und Peer-Bewertung, digitale Test- und Diagnosesysteme, formative Assessments, e-Portfolios). Diese gebe ich in meinem Kollegium und in Fortbildungen weiter."}], "pd": {"primary": "Leistung, Feedback & Lernstand", "secondary": "Digitale Tools & Anwendungen"}}, {"id": "4.2", "title": "Analyse der Lernevidenz", "ki": false, "intro": "Beispiele: Quiz, Bearbeitungsstand auf der Lernplattform, Umfrage, Auswertung in Tabellen, Learning Analytics", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "4.2-I", "text": "Ich weiss, dass sich Lernprozesse digital auswerten lassen, mache davon aber kaum Gebrauch.", "rich": "Ich weiss, dass sich Lernprozesse digital auswerten lassen, **mache davon aber kaum Gebrauch**.", "original": "Ich bin mir bewusst, dass die Effektivität von Lernprozessen auch mittels digitaler Medien analysiert werden kann, mache davon aber kaum oder gar keinen Gebrauch."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "4.2-II", "text": "Ich probiere digitale Werkzeuge aus, um im Unterricht schnell den Lernstand zu sehen.", "rich": "Ich probiere digitale Werkzeuge aus, um im Unterricht **schnell den Lernstand** zu sehen.", "original": "Ich versuche, digitale Tools während des Unterrichts zu nutzen, um zeitnahes Feedback zur grundlegenden Beteiligung und Effektivität des Lernprozesses zu erhalten (z. B. digitale Quizze oder Abfragen, Online-Rückmeldung zum Bearbeitungsstand von Aufgaben)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "4.2-III", "text": "Ich nutze regelmässig digitale Daten, um Beteiligung und Lernfortschritt einzuschätzen.", "rich": "Ich nutze regelmässig **digitale Daten**, um Beteiligung und Lernfortschritt einzuschätzen.", "original": "Ich nutze regelmässig digitale Tools und die Nutzungsdaten der Lernenden, um die Beteiligung und Effektivität der Lernprozesse zu beurteilen und zeitnah Feedback zum Lernverhalten geben zu können (z. B. Online-Umfragen, Formulare, Umfragen, Tabellenkalkulationen)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "4.2-IV", "text": "Ich werte Lerndaten bewusst aus, um individuelle Rückmeldungen zu geben.", "rich": "Ich werte Lerndaten bewusst aus, um **individuelle Rückmeldungen** zu geben.", "original": "Ich setze digitale Tools systematisch zur Datenerzeugung, -visualisierung und Analyse des Lernverhaltens der Lernenden ein, um zeitnah individuelles Feedback zur Lernentwicklung geben zu können (z. B. Tests, Beurteilungssysteme, Learning Analytics)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "4.2-V", "text": "Ich prüfe, welche Daten wirklich helfen, und unterstütze Kolleginnen und Kollegen dabei.", "rich": "Ich **prüfe, welche Daten wirklich helfen**, und unterstütze Kolleginnen und Kollegen dabei.", "original": "Ich analysiere und bewerte regelmässig verschiedene Möglichkeiten der Nutzung digitaler Daten zur Optimierung des Lernprozesses und zur Anpassung eigener Lehrstrategien. Meine Kolleginnen und Kollegen unterstütze ich bei der Erhebung und Analyse digital erfasster Daten zum Lernprozess."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "4.2-VI", "text": "Ich entwickle Vorgehensweisen zur Auswertung von Lerndaten und gebe sie weiter.", "rich": "Ich **entwickle Vorgehensweisen zur Auswertung** von Lerndaten und gebe sie weiter.", "original": "Ich initiiere und fördere in meiner Schule und ihrem Umfeld Strategien und Praktiken, die helfen, mittels Datengenerierung Lernprozesse zu beobachten. Mein diesbezügliches Wissen gebe ich in Kollegium und auf Fortbildungen weiter."}], "pd": {"primary": "Leistung, Feedback & Lernstand", "secondary": "Künstliche Intelligenz"}}, {"id": "4.3", "title": "Feedback und Planung", "ki": false, "intro": "Beispiele: Online-Übungen mit automatischer Rückmeldung, digitale Kommentare, Peer-Feedback, Umfragen", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "4.3-I", "text": "Ich weiss, dass ich digital Feedback geben kann, tue es aber kaum.", "rich": "Ich weiss, dass ich digital Feedback geben kann, **tue es aber kaum**.", "original": "Ich bin mir bewusst, dass digitale Technologien genutzt werden können, um Lernenden Feedback zu geben, mache davon aber noch keinen oder kaum Gebrauch (z. B. Online-Übungen, Online-Abfragen, automatisiertes Feedback)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "4.3-II", "text": "Ich probiere digitale Werkzeuge für individuelles Feedback aus, etwa Kommentare in Aufgaben.", "rich": "Ich probiere digitale Werkzeuge für **individuelles Feedback** aus, etwa Kommentare in Aufgaben.", "original": "Ich versuche digitale Tools zu nutzen, die individuelles Feedback unterstützen (z. B. Forum mit Peer-Feedback, Sternebewertung, digitale Anmerkungen zu Aufgaben)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "4.3-III", "text": "Ich gebe regelmässig digitales Feedback, teils auch automatisiert.", "rich": "Ich gebe regelmässig digitales Feedback, **teils auch automatisiert**.", "original": "Ich nutze verschiedene digitale Technologien, um den Lernenden inhaltliches (auch automatisiertes) Feedback zu geben (z. B. Online-Tests mit automatischer Auswertung, Online-Umfragen mit visueller Darstellung der Ergebnisse)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "4.3-IV", "text": "Ich setze digitales Feedback bewusst ein, um einzelne Lernende gezielt zu unterstützen.", "rich": "Ich setze digitales Feedback bewusst ein, um **einzelne Lernende gezielt** zu unterstützen.", "original": "Ich setze digitale Medien systematisch zur Verbesserung der Wirksamkeit von Feedback und individueller Lernunterstützung ein."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "4.3-V", "text": "Ich prüfe, welche Feedbackformen wirken, und unterstütze Kolleginnen und Kollegen dabei.", "rich": "Ich **prüfe, welche Feedbackformen wirken**, und unterstütze Kolleginnen und Kollegen dabei.", "original": "Ich analysiere und bewerte regelmässig verschiedene Methoden zu digital gestütztem Feedback und optimiere dahingehend die Wahl digitaler Werkzeuge und eigener Lehrstrategien. Meine Kolleginnen und Kollegen unterstütze ich dabei."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "4.3-VI", "text": "Ich entwickle Feedbackkonzepte, auch für die Unterrichtsplanung, und gebe sie weiter.", "rich": "Ich **entwickle Feedbackkonzepte**, auch für die Unterrichtsplanung, und gebe sie weiter.", "original": "Ich initiiere und fördere eine Strategie, die das Geben, Empfangen und Analysieren von Feedback erleichtert, um die Planung weiterer Massnahmen zu unterstützen (z. B. e-Portfolios, kontextabhängiges Feedback, digitales Storytelling). Mein zugehöriges Wissen gebe ich in Kollegium und Fortbildung weiter."}], "pd": {"primary": "Leistung, Feedback & Lernstand", "secondary": "Didaktik & Unterrichtsdesign"}}]}, {"id": "5", "title": "Schülerorientierung", "short": "Schülerorientierung", "description": "Mit digitalen Medien Teilhabe ermöglichen, differenzieren und Lernende aktivieren.", "subareas": [{"id": "5.1", "title": "Barrierefreiheit und digitale Teilhabe", "ki": false, "intro": "Beispiele: Zugang zu Geräten und Internet, Vorlesefunktion, einfache Sprache, barrierefreie Dokumente", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "5.1-I", "text": "Ich kenne digitale Hürden für Lernende, habe aber kaum Ansätze, sie abzubauen.", "rich": "Ich kenne digitale Hürden für Lernende, **habe aber kaum Ansätze**, sie abzubauen.", "original": "Ich kenne die potenziellen Einschränkungen und Barrieren Lernender in Bezug auf digitale Technologien (z. B. begrenzter Zugang zu digitalen Geräten und/oder zum Internet, Lernschwierigkeiten), sehe aber noch keine oder nur geringe Ansätze zur besseren digitalen Teilhabe."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "5.1-II", "text": "Ich achte beim Einsatz digitaler Mittel auf Zugang und besondere Bedürfnisse der Lernenden.", "rich": "Ich achte beim Einsatz digitaler Mittel auf **Zugang und besondere Bedürfnisse** der Lernenden.", "original": "Ich versuche digitale Technologien so einzusetzen, dass ein gleichberechtigter Bildungszugang möglich ist. Dabei berücksichtige ich elementar den Kontext und die Bedürfnisse der Lernenden (z. B. Bereitstellung von Geräten, Zugang zur Infrastruktur, familiärer Kontext, besondere Lernbedürfnisse)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "5.1-III", "text": "Ich sorge regelmässig dafür, dass alle Lernenden meine digitalen Angebote nutzen können.", "rich": "Ich sorge regelmässig dafür, dass **alle Lernenden** meine digitalen Angebote nutzen können.", "original": "Ich nutze verschiedene digitale Technologien für eine gleichberechtigte und integrative Bildung und stelle sicher, dass alle Lernenden Zugang zu den von mir bereitgestellten digitalen Lernangeboten haben (z. B. Zugang zur Infrastruktur, adaptive und unterstützende Technologien wie Bildschirmlesegeräte, alternative Tastaturen, barrierefreie Tools, Verwendung von leichter Sprache)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "5.1-IV", "text": "Ich gestalte digitale Lernangebote bewusst barrierefrei, passend zu den Bedürfnissen der Lernenden.", "rich": "Ich gestalte digitale Lernangebote **bewusst barrierefrei**, passend zu den Bedürfnissen der Lernenden.", "original": "Ich wähle digitale Technologien zielgerichtet aus und setze diese ein, um integrative Lernaktivitäten zu entwickeln. Ich erarbeite Konzepte und gestalte Ressourcen entsprechend den Bedürfnissen der Lernenden (z. B. Integration verschiedener Tools, Verwendung von speziellem Layout, Struktur und Sprache)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "5.1-V", "text": "Ich prüfe meinen Unterricht auf Barrieren und tausche mich darüber im Kollegium aus.", "rich": "Ich **prüfe meinen Unterricht auf Barrieren** und tausche mich darüber im Kollegium aus.", "original": "Ich reflektiere das digitale Lehren und Lernen unter dem Blickwinkel barrierefreier und integrativer Ansätze und tausche mich mit Kolleginnen und Kollegen darüber aus, um den Bedürfnissen und Fähigkeiten aller Lernenden gerecht zu werden (z. B. multimodale Präsentation von Informationen, Anpassung von Merkmalen zur Förderung der Barrierefreiheit wie Schriftgrösse und Layout, Entwicklung der digitalen Fähigkeiten der Schüler)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "5.1-VI", "text": "Ich entwickle Konzepte für digitale Teilhabe, auch für Eltern, und gebe sie weiter.", "rich": "Ich **entwickle Konzepte für digitale Teilhabe**, auch für Eltern, und gebe sie weiter.", "original": "Ich entwickle und multipliziere Konzepte und fördere Strategien für den gleichberechtigten Zugang zu Bildung durch den Einsatz digitaler Technologien (z. B. Medienbildung für Lernende und deren Eltern, Konzepte für Barrierefreiheit)."}], "pd": {"primary": "Inklusion, Differenzierung & Sprachbildung", "secondary": "Digitale Tools & Anwendungen"}}, {"id": "5.2", "title": "Differenzierung", "ki": false, "intro": "Beispiele: Aufgaben auf verschiedenen Niveaus, adaptive Übungsprogramme, Lernpfade, individuelle Lernpläne", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "5.2-I", "text": "Ich kenne digitale Möglichkeiten zur Differenzierung, nutze sie aber sehr selten.", "rich": "Ich kenne digitale Möglichkeiten zur Differenzierung, **nutze sie aber sehr selten**.", "original": "Ich kenne digitale Technologien zur Differenzierung und Individualisierung des Lernens (z. B. Anpassung des Unterrichts an die Bedürfnisse verschiedener Gruppen von Lernenden, individuelle Unterstützung von Lernenden), nutze diese aber nur sehr selten."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "5.2-II", "text": "Ich probiere digitale Übungen oder Lernspiele zur Differenzierung aus.", "rich": "Ich probiere **digitale Übungen oder Lernspiele** zur Differenzierung aus.", "original": "Ich versuche digitale Technologien für die Differenzierung und Individualisierung meines Unterricht zu integrieren (z. B. Quizze und Lernspiele, Online-Lernumgebungen)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "5.2-III", "text": "Ich nutze regelmässig digitale Angebote auf verschiedenen Niveaus.", "rich": "Ich nutze regelmässig digitale Angebote auf **verschiedenen Niveaus**.", "original": "Ich nutze verschiedene digitale Technologien beim Lehren und Lernen, um auf individuelle Lernbedürfnisse einzugehen (z. B. Quizze mit mit verschiedenen Schwierigkeitsgraden, differenzierte Online-Übungsaktivitäten, differenzierte Lernangebote in mebis, automatisiertes individuelles Feedback)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "5.2-IV", "text": "Ich gestalte individualisierte Lernumgebungen für die Bedürfnisse meiner Lernenden.", "rich": "Ich gestalte **individualisierte Lernumgebungen** für die Bedürfnisse meiner Lernenden.", "original": "Ich verwende gezielt digitale Technologien, um individualisierte Lernumgebungen für die spezifischen Bedürfnisse der Lernenden zu entwickeln (z. B. Beachtung des Niveaus, der Lerngeschwindigkeit und der Präferenzen Lernender durch selbst entwickelte und auf die jeweiligen Lernziele abgestimmte Quizze oder Lernspiele, Erstellung von differenziertem Material für Online-Lernumgebungen, wie z.B. mebis)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "5.2-V", "text": "Lernende gestalten ihre Lernwege mit; ich prüfe die Wirkung und passe meine Methoden an.", "rich": "Lernende **gestalten ihre Lernwege mit**; ich prüfe die Wirkung und passe meine Methoden an.", "original": "Ich gestalte meinen Unterricht so, dass die Lernenden in die Realisierung ihrer eigenen Lernwege einbezogen werden und ihren individuellen Lernbedürfnissen mithilfe von passenden digitalen Ressourcen folgen (z. B. personalisierte Lernpläne, Online-Tools, um Lernziele festzusetzen und den eigenen Fortschritt zu kontrollieren). Ich reflektiere ausserdem kritisch wie effektiv die eingesetzten Lehrstrategien die Differenzierung und Individualisierung fördern und passe meine Methoden entsprechend an."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "5.2-VI", "text": "Ich entwickle Konzepte für digitale Differenzierung und gebe sie weiter.", "rich": "Ich **entwickle Konzepte für digitale Differenzierung** und gebe sie weiter.", "original": "Ich entwickle und multipliziere Konzepte für digital gestützte Differenzierung und Individualisierung (z. B. Austausch bewährter inklusiver Lernmethoden, Online-Plattform mit Ressourcen)."}], "pd": {"primary": "Inklusion, Differenzierung & Sprachbildung", "secondary": "Didaktik & Unterrichtsdesign"}}, {"id": "5.3", "title": "Schüleraktivierung", "ki": false, "intro": "Beispiele: Lernspiele, interaktive Übungen, Erklärvideos der Lernenden, Simulationen, Robotik", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "5.3-I", "text": "Ich setze digitale Mittel für aktivierende Lernformen nur selten ein.", "rich": "Ich setze digitale Mittel für aktivierende Lernformen **nur selten** ein.", "original": "Ich nutze nur selten digitale Technologien, für motivierende und schüleraktivierende Lernformen. (z. B. Lernspiele, interaktive Aktivitäten)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "5.3-II", "text": "Ich probiere digitale Mittel aus, um Inhalte motivierend zu vermitteln.", "rich": "Ich probiere digitale Mittel aus, um Inhalte **motivierend zu vermitteln**.", "original": "Ich suche nach Wegen, um mithilfe digitaler Technologien Lerninhalte motivierend und schülergerecht zu vermitteln (z. B. Lernspiele, interaktive Aktivitäten, Simulationen, OER-Ressourcen)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "5.3-III", "text": "Ich aktiviere Lernende regelmässig digital, etwa mit selbst erstellten Erklärvideos.", "rich": "Ich aktiviere Lernende regelmässig digital, etwa mit **selbst erstellten Erklärvideos**.", "original": "Ich nutze sach- und situationsgerecht digitale Technologien zur Förderung des aktiven Engagements der Lernenden (z.B. Lernspiele, Edu-Breakout, Erstellung von Erklärvideos durch die Lernenden, Peer-Reviews, AR-Technologie u.a.)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "5.3-IV", "text": "Ich variiere digitale Aktivitäten bewusst, damit Lernende selbst aktiv werden.", "rich": "Ich variiere digitale Aktivitäten bewusst, damit Lernende **selbst aktiv werden**.", "original": "Ich gestalte meinen Unterricht zielgerichtet mit einer Vielzahl digitaler Technologien, um das aktive Engagement der Lernenden beim individuellen und gemeinschaftlichen Lernen und deren Eigenaktivität zu fördern (z. B. verschiedene sensorische Kanäle, Variation der Aktivitätstypen, kollaboratives Schreiben, Spiele und Simulationen, AR/VR )."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "5.3-V", "text": "Ich entwickle aktivierende Unterrichtskonzepte weiter und prüfe, welche Methoden wirken.", "rich": "Ich **entwickle aktivierende Unterrichtskonzepte weiter** und prüfe, welche Methoden wirken.", "original": "Ich gestalte und entwickle didaktische Konzepte, um die aktive Beschäftigung der Lernenden mit dem Lerngegenstand optimal zu fördern und evaluiere, inwiefern sich verschiedene Methoden dazu eignen, die Eigenaktivität der Lernenden zu erhöhen. (z. B. strukturiertes teambasiertes Lernen, Online-Diskussionen, Peer-Coaching und -Unterricht, e-Portfolios)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "5.3-VI", "text": "Ich gestalte neue Lernformen, etwa mit Robotik oder KI, und gebe sie weiter.", "rich": "Ich **gestalte neue Lernformen**, etwa mit Robotik oder KI, und gebe sie weiter.", "original": "Ich initiiere, fördere und multipliziere innovative Konzepte zur Förderung des digital gestützten eigenaktiven Lernens (z. B. Makerspace, Robotik, Programmierung, KI-Anwendungen, eigene Erstellung von komplexen Lernspielen)."}], "pd": {"primary": "Didaktik & Unterrichtsdesign", "secondary": "Digitale Tools & Anwendungen"}}]}, {"id": "6", "title": "Medienkompetenz der Lernenden", "short": "Medienkompetenz der Lernenden", "description": "Lernende befähigen, digitale Medien kompetent, kreativ und reflektiert zu nutzen.", "subareas": [{"id": "6.1", "title": "Basiskompetenzen", "ki": false, "intro": "Worum es geht: Lernende nutzen digitale Werkzeuge sicher und lösen einfache Probleme selbst. Beispiele: Suchmaschine, Hilfefunktion, Gerät neu starten, Daten sichern", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "6.1-I", "text": "Ich weiss, dass Lernende digitale Werkzeuge selbstständig nutzen können, fördere dies aber kaum.", "rich": "Ich weiss, dass Lernende digitale Werkzeuge selbstständig nutzen können, **fördere dies aber kaum**.", "original": "Ich bin mir bewusst, dass die Lernenden digitale Medien und Werkzeuge sachorientiert nutzen können, um Aufgaben zu verstehen und dabei auftretende Probleme zu lösen, nutze diese Möglichkeit in meinem Unterricht nicht oder nur selten (z. B. Nutzung einer Suchmaschine, von Hilfefunktionen)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "6.1-II", "text": "Ich probiere Aufgaben aus, bei denen Lernende einfache technische Probleme selbst lösen.", "rich": "Ich probiere Aufgaben aus, bei denen Lernende **einfache technische Probleme selbst lösen**.", "original": "Ich habe Lernaktivitäten ausprobiert, die die Lernenden ermutigen, digitale Medien und Werkzeuge sachgerecht zu nutzen, Aufgaben zu verstehen und dabei auftretende Probleme zu lösen (z. B. einfache technische Lösungsstrategien wie Computer neu starten, Internetverbindung prüfen, Datensicherungen durchführen)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "6.1-III", "text": "Meine Lernenden nutzen digitale Werkzeuge regelmässig auch für umfangreichere Aufgaben.", "rich": "Meine Lernenden nutzen digitale Werkzeuge regelmässig auch für **umfangreichere Aufgaben**.", "original": "Ich nutze sach- und situationsgerecht Lernaktivitäten, bei denen die Lernenden digitale Medien und Werkzeuge überlegt und systematisch für komplexere Aufgabenfelder nutzen (z. B. Informationen mit digitalen Werkzeugen finden und ordnen, analysieren, Schlussfolgerung ziehen und Ergebnisse fixieren; Erstellung und Konzeption einer Präsentation zu einem umfangreicheren Themenbereich)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "6.1-IV", "text": "Ich plane Projekte, in denen Lernende selbst passende Werkzeuge wählen und kreativ einsetzen.", "rich": "Ich plane Projekte, in denen Lernende **selbst passende Werkzeuge wählen** und kreativ einsetzen.", "original": "Ich wähle und verwende Lernkonzepte, in denen z.B. im Rahmen von Projektarbeiten Lernende aus einem breiten Medienangebot gezielt das Passende auswählen und dabei nach verschiedenen innovativen und kreativen Lösungen suchen, die in neuen Situationen und Kontexten angewandt werden können (z.B. Projektarbeit im Geografieunterricht unter Verwendung von geografischen Informationssystemen (GIS); Nutzung von virtuellen Umgebungen im Geschichts- oder Biologieunterricht, Modellierungen)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "6.1-V", "text": "Ich prüfe, welche Methoden sich bewähren, und gebe mein Wissen im Kollegium weiter.", "rich": "Ich **prüfe, welche Methoden sich bewähren**, und gebe mein Wissen im Kollegium weiter.", "original": "Ich reflektiere kritisch inwiefern sich Strategien und Methoden zur Nutzung von Medienangeboten bei schulischen Lernaktivitäten und Aufgaben didaktisch und pädagogisch eignen, berücksichtige dabei insbesondere auch die Möglichkeiten und Grenzen der digitalen Werkzeuge vor Ort, und gebe mein Wissen im Kollegenkreis weiter (z.B. Mitarbeit im Medienkonzeptteam, Referententätigkeit im SCHILF-Bereich, Multiplikation von Strategien zur Nutzung schulischer IT-Systeme wie mebis)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "6.1-VI", "text": "Ich entwickle neue Lernszenarien oder Materialien und gebe sie über die Schule hinaus weiter.", "rich": "Ich **entwickle neue Lernszenarien** oder Materialien und gebe sie über die Schule hinaus weiter.", "original": "Ich trage zur Entwicklung und Multiplikation innovativer und kreativer Lernszenarien für die Nutzung von Medienangeboten bei schulischen Lernaktivitäten und Aufgaben bei. Dabei analysiere und modelliere ich den Einsatz von digitalen Werkzeugen und bereite sie didaktisch auf (z.B. Entwicklung von Lernsoftware oder Schulbüchern mit digitalen Zusatzangeboten, Entwicklung von Unterrichtskonzepten mit digitalen Medien, Verfassen von Handreichungen für den Unterricht, umfassende regionale bzw. zentrale Referententätigkeit)."}], "pd": {"primary": "Medienkompetenz & Medienkritik", "secondary": "Digitale Tools & Anwendungen"}}, {"id": "6.2", "title": "Suchen und Verarbeiten", "ki": false, "intro": "Beispiele: Suchmaschinen und Suchfilter, Quellen vergleichen und zitieren, Diagramme lesen, Falschinformationen erkennen", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "6.2-I", "text": "Ich kenne Aufgaben zur digitalen Informationssuche, setze sie aber selten ein.", "rich": "Ich kenne Aufgaben zur digitalen Informationssuche, **setze sie aber selten ein**.", "original": "Ich kenne Lernaktivitäten mit digitalen Medien, die die Such- und Verarbeitungsstrategien der Lernenden verbessern können, nutze sie jedoch im Unterricht nicht oder nur selten (z.B. Suche nach digitalen Informationen mit einer Suchmaschine, Bewertung der gefundenen Informationen, Lesen von Diagrammen, Lesen und Verstehen von Daten, Erstellung einfacher digitaler Inhalte wie Texte, Tabellen oder Bilder)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "6.2-II", "text": "Ich probiere Rechercheaufgaben aus und lehre Lernende, Quellen korrekt anzugeben.", "rich": "Ich probiere Rechercheaufgaben aus und lehre Lernende, **Quellen korrekt anzugeben**.", "original": "Ich habe Lernaktivitäten ausprobiert, die die Lernenden dazu anregen, digitale Medien zur Informationsgewinnung und -verarbeitung einzusetzen. Dabei bringe ich Lernenden bei, Quellen korrekt anzugeben und zu zitieren (z.B. bei Online-Recherchen, Festlegung von Suchkriterien, Vergleich verschiedener Quellen, Interpretation von Daten, Erstellung digitaler Inhalte)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "6.2-III", "text": "Lernende suchen und vergleichen regelmässig Informationen und prüfen ihre Verlässlichkeit.", "rich": "Lernende suchen und vergleichen regelmässig Informationen und **prüfen ihre Verlässlichkeit**.", "original": "Ich nutze sach- und situationsgerecht Lernaktivitäten und Aufgaben, die von den Lernenden verlangen, Informationen und Daten aus verschiedenen Quellen zu suchen, zu vergleichen, kritisch auf ihre Verlässlichkeit zu bewerten und sie in komplexeren digitalen Inhalten zu kombinieren. (z. B. Nutzung von unterschiedlichen und altersgerechten Suchmaschinen; Verwendung von Suchfiltern; Festlegung von Auswahlkriterien, Erkennen von Ungenauigkeiten, fehlenden Informationen oder Voreingenommenheit, Gegenprüfung verschiedener Quellen zur Beurteilung der Glaubwürdigkeit, Umgang mit Fehlinformationen, Rassismus und Fremdenfeindlichkeit)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "6.2-IV", "text": "Ich gestalte Aufgaben bewusst so, dass Lernende Informationen bewerten und aufbereiten.", "rich": "Ich gestalte Aufgaben bewusst so, dass Lernende Informationen **bewerten und aufbereiten**.", "original": "Ich gestalte den Unterricht sach- und situationsgerecht mit einer Vielzahl an verschiedenen Lernaktivitäten und Aufgaben so, dass die Lernenden Informationen und Daten kritisch suchen, bewerten, kombinieren und aufbereiten können. (z. B. systematische Nutzung unterschiedlicher Suchmaschinen und Kombination von Suchfiltern; Analyse der Wahl des Informationsmediums, der Quelle, des Zwecks, der Transparenz der Algorithmen, die verwendet werden, um zu entscheiden, welche Art von Informationen und Daten angezeigt werden)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "6.2-V", "text": "Ich entwickle Unterrichtskonzepte zur Recherche weiter und teile sie im Kollegium.", "rich": "Ich **entwickle Unterrichtskonzepte zur Recherche weiter** und teile sie im Kollegium.", "original": "Ich reflektiere kritisch, inwiefern sich verschiedene Methoden dazu eignen, Such- und Verarbeitungsstrategien beim Einsatz digitaler Medien und Werkzeuge zu fördern, entwickle Unterrichtskonzepte entsprechend weiter und multipliziere mein Wissen im Kollegenkreis (z. B. Entwicklung von Unterrichtskonzepten für Such- und Verarbeitungsstrategien mit digitalen Medien, Verfassen von Handreichungen für den Unterricht, Referententätigkeit auf SCHILF-Ebene)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "6.2-VI", "text": "Ich entwickle neue Lernszenarien zur Informationskompetenz und gebe sie weiter.", "rich": "Ich **entwickle neue Lernszenarien zur Informationskompetenz** und gebe sie weiter.", "original": "Ich trage zur Entwicklung und Multiplikation von innovativen Lernszenarien bei. Diese fördern Kompetenzen zur Informationsgewinnung und -verarbeitung - auch unter Berücksichtigung neuer medialer Entwicklungen (z.B. Entwicklung bestimmter Kriterien zur kritischen Bewertung von Suchergebnissen kommerzieller Suchmaschinen; Nutzung von (neuen) Spezial-Suchmaschinen)."}], "pd": {"primary": "Medienkompetenz & Medienkritik", "secondary": "Künstliche Intelligenz"}}, {"id": "6.3", "title": "Kommunizieren und Kooperieren", "ki": false, "intro": "Beispiele: Klassenchat, Online-Meeting, gemeinsame Dokumente, Netiquette, Peer-Feedback, Online-Diskussion", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "6.3-I", "text": "Ich kenne Aufgaben zur digitalen Kommunikation der Lernenden, setze sie aber selten ein.", "rich": "Ich kenne Aufgaben zur digitalen Kommunikation der Lernenden, **setze sie aber selten ein**.", "original": "Ich kenne Lernaktivitäten, die die digital gestützte Kommunikation und Zusammenarbeit der Lernenden fördern könnten, nutze sie jedoch nicht oder nur selten (z. B. Nutzung von E-Mails, Instant Messaging, sozialen Netzwerken usw. zur Kommunikation mit Lehrkräften und Mitschülerinnen und Mitschülern)."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "6.3-II", "text": "Ich probiere Aufgaben aus, bei denen Lernende digital kommunizieren und zusammenarbeiten.", "rich": "Ich probiere Aufgaben aus, bei denen Lernende **digital kommunizieren und zusammenarbeiten**.", "original": "Ich habe Lernaktivitäten ausprobiert, die Lernende dazu ermutigen, mithilfe digitaler Medien und Werkzeuge mit anderen Lernenden, ihren Lehrkräften und mit Dritten zu kommunizieren und zu kooperieren (z. B. durch Online-Meetings, Diskussionsforen, Klassen-Chat)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "6.3-III", "text": "Lernende kommunizieren regelmässig digital; wir erarbeiten gemeinsam Regeln dafür.", "rich": "Lernende kommunizieren regelmässig digital; wir erarbeiten gemeinsam **Regeln dafür**.", "original": "Ich setze sach- und situationsgerecht Lernaktivitäten ein, bei denen Lernende digitale Medien und Werkzeuge effektiv und verantwortungsbewusst für die Kommunikation nutzen. Ich entwickle mit den Lernenden Kommunikations- und Verhaltensregeln für den digitalen Raum. Ich unterstütze sie dabei, Kommunikationsstrategien und -kanäle angemessen auszuwählen und sich der kulturellen und sozialen Vielfalt in digitalen Umgebungen bewusst zu sein (z. B. Verwendung eines geeigneten Mediums für die digitale Kommunikation der Lernenden, Etablierung einer „Netiquette“)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "6.3-IV", "text": "Ich plane Aufgaben bewusst so, dass Lernende digital mitdiskutieren und Feedback geben.", "rich": "Ich plane Aufgaben bewusst so, dass Lernende digital **mitdiskutieren und Feedback geben**.", "original": "Ich gestalte eine Vielzahl an verschiedenen Lernaktivitäten und Aufgaben, bei denen die Lernenden digitale Medien und Werkzeuge für die Kommunikation und Kooperation nutzen. Dabei unterstütze und motiviere ich sie, digitale Medien und Werkzeuge zum Peer-Feedback sowie zur Teilnahme an öffentlichen Diskursen zu nutzen und diese aktiv und bewusst für die gesellschaftliche Teilhabe zu verwenden. Ich prüfe und reflektiere vereinbarte Kommunikations- und Verhaltensregeln gemeinsam mit den Lernenden (z. B. Verwendung von digitalen Kollaborations-Tools, Nutzung einer gemeinsamen Lernumgebung, Bearbeitung gemeinsamer Online-Dokumente, Respektieren der Ideen und der Vielfalt anderer, während man zur Teamarbeit beiträgt, Austausch von Nachrichten über multikulturelle Netzwerke, Schaffung positiver Verbindungen und Aufbau von Kontakten, Teilnahme an der öffentlichen Diskussion in Foren)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "6.3-V", "text": "Ich entwickle meine Konzepte zur digitalen Kommunikation weiter und teile sie im Kollegium.", "rich": "Ich **entwickle meine Konzepte zur digitalen Kommunikation weiter** und teile sie im Kollegium.", "original": "Ich reflektiere kritisch, inwiefern sich verschiedene Methoden dazu eignen, Kompetenzen der Lernenden zur effektiven und verantwortungsbewussten digital gestützten Kommunikation und Zusammenarbeit sowie zur Partizipation in einer digitalisierten Welt zu fördern, entwickle Unterrichtskonzepte entsprechend weiter und multipliziere mein Wissen im Kollegenkreis (z. B. Nutzung erweiterter Funktionen von Kollaborations-Tools, Diskussion mit den Lernenden über die Bedürfnisse der Kommunikation und Kooperation, Referententätigkeit auf SCHILF-Ebene)."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "6.3-VI", "text": "Ich gestalte neue Formen digitaler Zusammenarbeit im Unterricht und gebe sie weiter.", "rich": "Ich **gestalte neue Formen digitaler Zusammenarbeit** im Unterricht und gebe sie weiter.", "original": "Ich entwickle innovative Lernszenarien zur Förderung von Kompetenzen zur Kommunikation und Zusammenarbeit der Lernenden sowie zur Partizipation in einer digitalisierten Welt – auch unter Einbezug neuer kommunikationstechnischer Entwicklungen (z. B. Entwicklung neuer digitaler Kollaborationsformen im unterrichtlichen Kontext)."}], "pd": {"primary": "Medienkompetenz & Medienkritik", "secondary": "Schülerinnenwelten & Gesellschaft"}}, {"id": "6.4", "title": "Produzieren und Präsentieren", "ki": false, "intro": "Beispiele: Texte, Fotos, Präsentationen, Audio und Video, digitale Geschichten, Blog, E-Portfolio", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "6.4-I", "text": "Ich kenne Aufgaben, bei denen Lernende digitale Inhalte gestalten, setze sie aber kaum ein.", "rich": "Ich kenne Aufgaben, bei denen Lernende digitale Inhalte gestalten, **setze sie aber kaum ein**.", "original": "Ich kenne Lernaktivitäten, die Lernende dazu ermutigen, sich mit digitalen Mitteln auszudrücken (z. B. in Form von Texten, Fotos, Bildern, Präsentationen), setze diese jedoch kaum ein."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "6.4-II", "text": "Ich probiere Aufgaben aus, bei denen Lernende Texte, Präsentationen oder Videos erstellen.", "rich": "Ich probiere Aufgaben aus, bei denen Lernende **Texte, Präsentationen oder Videos** erstellen.", "original": "Ich habe Lernaktivitäten ausprobiert, die die Lernenden dazu ermutigen, digitale Inhalte zu erstellen und zu bearbeiten (z. B. Texte, Präsentationen, Audio- und Video-Inhalte)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "6.4-III", "text": "Lernende drücken ihre Ideen regelmässig kreativ mit digitalen Werkzeugen aus.", "rich": "Lernende drücken ihre Ideen regelmässig **kreativ mit digitalen Werkzeugen** aus.", "original": "Ich setze verschiedene Lernaktivitäten sach- und situationsgerecht um, die von meinen Lernenden verlangen, ihre Ideen kreativ zum Ausdruck zu bringen und zu vermitteln, indem sie geeignete digitale Tools verwenden (z. B. Visualisierungen, Simulationen, digitale Stories, Werkzeuge zum Videoschnitt)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "6.4-IV", "text": "Ich wähle Aufgaben bewusst so, dass Lernende Ergebnisse präsentieren und Urheberrechte beachten.", "rich": "Ich wähle Aufgaben bewusst so, dass Lernende Ergebnisse **präsentieren und Urheberrechte beachten**.", "original": "Ich identifiziere aus einer Vielzahl verschiedener Lernaktivitäten gezielt geeignete aus und verwende sie, um Lernende zu unterstützen, ihre Meinung und Arbeitsergebnisse zu präsentieren und zu dokumentieren (z.B. in Wikis, Blogs oder E-Portfolios) und dabei Urheberrechtsvorschriften einzuhalten und Lizenzen zu wahren."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "6.4-V", "text": "Ich prüfe, welche Aufgaben sich bewähren, und berate mein Kollegium.", "rich": "Ich **prüfe, welche Aufgaben sich bewähren**, und berate mein Kollegium.", "original": "Ich reflektiere und bewerte kritisch Lernaktivitäten zur Förderung der digitalen Fertigkeiten bei der (Neu-)Erstellung von Inhalten durch die Lernenden und zur Förderung der kollaborativen Nutzung (z. B. digitale Stories, e-Portfolios). Ausserdem berate ich mein Kollegium diesbezüglich."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "6.4-VI", "text": "Ich entwickle neue Formen digitaler Produktion und gebe sie in Weiterbildungen weiter.", "rich": "Ich **entwickle neue Formen digitaler Produktion** und gebe sie in Weiterbildungen weiter.", "original": "Ich entwickle innovative Lernszenarien zur Förderung digital gestützter kreativer Produkte, Präsentationen und Publikationen der Lernenden (z. B. Veröffentlichung komplexer Medienprodukte, gemeinsame Erstellung von mobilen Apps, Unterhaltung von Makerspaces, Förderung von Audio- und Videoübertragungen) und multipliziere diese Kompetenzen in regionalen oder überregionalen Fortbildungen."}], "pd": {"primary": "Digitale Tools & Anwendungen", "secondary": "Medienkompetenz & Medienkritik"}}, {"id": "6.5", "title": "Analysieren und Reflektieren", "ki": false, "intro": "Beispiele: Datenschutz, Urheberrecht, App-Berechtigungen, Fake News, digitaler Fussabdruck", "levels": [{"level": 1, "roman": "I", "label": "Einsteigen", "itemId": "6.5-I", "text": "Ich kenne wenige Aufgaben zu Recht und Ethik im Digitalen und nutze sie kaum.", "rich": "Ich kenne wenige Aufgaben zu Recht und Ethik im Digitalen und **nutze sie kaum**.", "original": "Ich kenne in geringem Umfang Lernaktivitäten, die die Lernenden befähigen, die rechtlichen und ethischen Auswirkungen der Nutzung digitaler Technologien zu verstehen (z. B. Weitergabe von personenbezogenen Daten und sensiblen Informationen anderer, Umgang mit privaten Einstellungen in Online-Apps), aber berücksichtige sie in meinem Unterricht kaum."}, {"level": 2, "roman": "II", "label": "Entdecken", "itemId": "6.5-II", "text": "Ich sensibilisiere Lernende ab und zu für rechtliche und ethische Fragen, etwa Fake News.", "rich": "Ich sensibilisiere Lernende ab und zu für **rechtliche und ethische Fragen**, etwa Fake News.", "original": "Ich versuche zielgerichtet Lernende dahingehend zu sensibilisieren, welche rechtlichen und ethischen Auswirkungen die Nutzung digitaler Technologien haben kann (z. B. Freigabe von urheberrechtlich geschützten digitalen Inhalten, Akzeptieren von Genehmigungen bei der Installation von Apps) und für eine interessengeleitete Setzung medialer Inhalte zu sensibilisieren (z.B. Erkennen von Fake News)."}, {"level": 3, "roman": "III", "label": "Anwenden", "itemId": "6.5-III", "text": "Lernende gehen in meinem Unterricht regelmässig verantwortungsvoll mit digitalen Inhalten um.", "rich": "Lernende gehen in meinem Unterricht regelmässig **verantwortungsvoll mit digitalen Inhalten** um.", "original": "Ich verwende sach- und situationsgerecht verschiedene digitale Lernaktivitäten, die von den Lernenden sowohl bei der Nutzung als auch bei der Erstellung von digitalen Inhalten eine verantwortungsvolle, ethisch reflektierte und sozialverantwortliche Vorgehensweise verlangen (z. B. kritische Bewertung von Online-Informationen, Reaktion auf Falschinformationen, positives Online-Verhalten, Einhaltung von Datenschutz- und Urheberrechtsbestimmungen)."}, {"level": 4, "roman": "IV", "label": "Integrieren", "itemId": "6.5-IV", "text": "Ich gestalte Lernumgebungen, in denen Lernende den Einfluss digitaler Medien analysieren.", "rich": "Ich gestalte Lernumgebungen, in denen Lernende **den Einfluss digitaler Medien analysieren**.", "original": "Ich gestalte durch systematische Auswahl verschiedener Aktivitäten Lernumgebungen, um Lernende bei der vertiefenden Analyse und Beurteilung von Inhalten und Einflüssen digitaler Technologien zu fördern und sie zu einem verantwortungsbewussten Umgang mit digitalen Medien zu befähigen (z. B. Verfolgung ihres digitalen Fussabdrucks, Verwaltung ihrer digitalen Identität, Kenntnis der Nutzungsbedingungen verschiedener Medien und Anwendungen, Verwaltung von Anwendungseinstellungen)."}, {"level": 5, "roman": "V", "label": "Entwickeln", "itemId": "6.5-V", "text": "Ich prüfe, welche Methoden zur Medienanalyse wirken, und teile mein Wissen im Kollegium.", "rich": "Ich **prüfe, welche Methoden zur Medienanalyse wirken**, und teile mein Wissen im Kollegium.", "original": "Ich reflektiere kritisch, inwiefern sich verschiedene Methoden dazu eignen, Medienangebote und digitale Werkzeuge im Unterricht umfassend zu analysieren und gestalte sie ggf. entsprechend um. Mein Wissen gebe ich im Kollegenkreis weiter."}, {"level": 6, "roman": "VI", "label": "Weitergeben", "itemId": "6.5-VI", "text": "Ich entwickle neue Konzepte zur kritischen Medienanalyse und gebe sie weiter.", "rich": "Ich **entwickle neue Konzepte zur kritischen Medienanalyse** und gebe sie weiter.", "original": "Ich entwickle und multipliziere innovative Konzepte und Lernszenarien zur kritischen Auseinandersetzung mit Inhalten, Gestaltungsmitteln, Wirkungsweisen und Einflüssen digitaler Technologien sowie Chancen und Risiken in den Medien."}], "pd": {"primary": "Medienkompetenz & Medienkritik", "secondary": "Schülerinnenwelten & Gesellschaft"}}]}], "pd": {"provider": "fobizz", "lead": "Schulentwicklung & Leadership", "themes": ["Didaktik & Unterrichtsdesign", "Team- und Beziehungsarbeit", "Leistung, Feedback & Lernstand", "Gesundheit & Professionalisierung", "Digitale Tools & Anwendungen", "Medienkompetenz & Medienkritik", "Schulentwicklung & Leadership", "Inklusion, Differenzierung & Sprachbildung", "Künstliche Intelligenz", "Schülerinnenwelten & Gesellschaft", "Programmieren & Informatik"]}};
